#!/usr/bin/env bash
# Synced from bootstrap: macos/tools/claude/files/.claude/hooks/npm-normalize.sh. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# The rewrite runs before the permission check: an npm-only deny or ask rule
# (Bash(npm publish:*)) does not match the pnpm command, so add a pnpm rule too.
# The PreToolUse hook of the Bash tool of Claude Code. When pnpm is on PATH, it
# changes npm to pnpm, npx to pnpm exec, and npm ci to
# pnpm install --frozen-lockfile. It gives no permission decision, so the
# changed command goes through the normal permission rules. With no change, it
# prints {}. The sed expressions are BSD sed expressions: no \s and no \b.

set -euo pipefail

input=$(cat)

# A command with a newline (a heredoc or a multi-line string) stays as it is.
if [[ "$(jq -r '.tool_input.command // "" | test("\n")' <<< "$input")" == "true" ]]; then
  echo '{}'
  exit 0
fi

if ! command -v pnpm > /dev/null 2>&1; then
  echo '{}'
  exit 0
fi

command=$(jq -r '.tool_input.command // ""' <<< "$input")

# A command with a quote or a backslash stays as it is: a ; & or | inside
# quoted or escaped text is not the start of a command.
if [[ "$command" == *[\'\"\\]* ]]; then
  echo '{}'
  exit 0
fi

# The start of a command: the start of the line, after ; & or |, or after $(.
start='(^|[;&|][[:space:]]*|\$\([[:space:]]*)'

# npx -> pnpm exec
rewritten=$(printf '%s\n' "$command" | sed -E "s/${start}npx[[:space:]]+/\\1pnpm exec /g")

# npm ci -> pnpm install --frozen-lockfile
rewritten=$(printf '%s\n' "$rewritten" | sed -E "s/${start}npm[[:space:]]+ci([[:space:]]|[;&|)]|$)/\\1pnpm install --frozen-lockfile\\2/g")

# npm -> pnpm (each other npm command)
rewritten=$(printf '%s\n' "$rewritten" | sed -E "s/${start}npm[[:space:]]+/\\1pnpm /g")

if [[ "$rewritten" == "$command" ]]; then
  echo '{}'
  exit 0
fi

jq -c --arg new "$rewritten" '{
  hookSpecificOutput: {
    hookEventName: "PreToolUse",
    updatedInput: (.tool_input | .command = $new)
  }
}' <<< "$input"
